const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start_date = '2024-11-01';
    const end_date = '2024-11-30';

    // Define the region for Punjab and Haryana using GEE's administrative boundaries.
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const punjab = gaul.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Punjab')
    ));
    const haryana = gaul.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Haryana')
    ));
    const region = punjab.merge(haryana).geometry();

    // 2. Data Acquisition & Check
    let viirsCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
      .filterDate(start_date, end_date)
      .filterBounds(region);

    const collectionSize = await viirsCollection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No VIIRS images found for November 2024 in Punjab and Haryana.`);
      console.log("C1");
      return;
    }
    console.log(`VIIRS images found: ${collectionSize}`);

    // Mask non-fire pixels (Detections == 0). Keep only active fire detections (Detections == 1).
    // The 'Detections' band is 1 for active fires, 0 otherwise.
    viirsCollection = viirsCollection.map(function(image) {
      return image.select('Detections').updateMask(image.select('Detections').eq(1));
    });

    // 3. Processing
    // Sum all fire detections across the entire collection into a single image.
    // Each pixel in the result will represent the total number of detections at that location.
    const summedDetections = viirsCollection.sum();

    // Calculate the total number of fire detections within the combined region.
    // Use a large enough scale (e.g., 1000m) to avoid memory issues with `reduceRegion` for large areas.
    // The VIIRS resolution is ~375m, but 1000m is generally safe for region reductions.
    const fireCountResult = await summedDetections.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('Detections').getInfo();

    // 4. Calculation & Validation
    const totalFires = fireCountResult;

    if (totalFires === null || isNaN(totalFires)) {
      console.log("Calculation of total fire detections failed. Result is null or NaN.");
      console.log("C3");
      return;
    }

    // Since we've masked to only include active fire pixels (Detections == 1),
    // a count of 0 implies no valid fire pixels, which is a valid result (no fires).
    // We only need to check if the *result* of the calculation is invalid (null/NaN).

    console.log(`Total fire detections in November 2024 for Punjab and Haryana: ${totalFires}`);

    // 5. Final Answer
    if (totalFires < 20000) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // Catch-all for other errors like incorrect band names, syntax errors, etc.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
